B.bXI=new A.dl("sab-5","Jangan bersedih atas apa yang telah pergi darimu, karena jika Allah menakdirkannya untukmu, ia takkan pernah menjadi milik orang lain.",null,"Imam Syafi'i","sabar","Sabar & Ujian",B.Nx)
