B.bXQ=new A.dl("doa-1","Berdoalah kepada-Ku, niscaya akan Kuperkenankan bagimu.","\u0627\u062f\u0652\u0639\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u0628\u0652 \u0644\u064e\u0643\u064f\u0645\u0652","QS. Ghafir: 60","doa","Doa & Taubat",B.Nz)
