B.bXr=new A.dl("sah-1","Orang yang paling berakal adalah orang yang paling banyak mengingat kematian dan paling siap menghadapinya.",null,"Ali bin Abi Thalib","sahabat","Sahabat & Ulama",B.Nx)
B.aQb=s([4278734968,4286961870],t.t)
