B.aQj=s([4280287522,4285464576],t.t)
B.bXy=new A.dl("sah-3","Bila lisanmu terjaga dari membicarakan aib orang lain, Allah akan menjaga aibmu di hadapan seluruh makhluk di hari kiamat.",null,"Utsman bin Affan","sahabat","Sahabat & Ulama",B.aQj)
B.aQt=s([4284229005,4282616226],t.t)
