B.aQm=s([4281998449,4292308343],t.t)
B.bXC=new A.dl("sah-6","Hisablah dirimu sendiri sebelum kalian dihisab, dan timbanglah amal perbuatanmu sebelum kelak ditimbang.",null,"Umar bin Khattab","sahabat","Sahabat & Ulama",B.aQm)
B.bXm=new A.dl("sah-7","Jangan menjelaskan tentang dirimu kepada siapa pun, karena yang menyukaimu tidak butuh itu, dan yang membencimu tidak percaya itu.",null,"Ali bin Abi Thalib","sahabat","Sahabat & Ulama",B.Ny)
B.aQy=s([4292022311,4293539917],t.t)
B.bXt=new A.dl("cin-1","Ridha Allah terletak pada ridha kedua orang tua, dan murka Allah terletak pada kemurkaan kedua orang tua.","\u0631\u0650\u0636\u064e\u0649 \u0627\u0644\u0631\u0651\u064e\u0628\u0651\u0650 \u0641\u0650\u064a \u0631\u0650\u0636\u064e\u0649 \u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650\u060c \u0648\u064e\u0633\u064e\u062e\u064e\u0637\u064f \u0627\u0644\u0631\u0651\u064e\u0628\u0651\u0650 \u0641\u0650\u064a \u0633\u064e\u062e\u064e\u0637\u0650 \u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650","HR. Tirmidzi no. 1899","cinta","Cinta & Keluarga",B.aQy)
B.aQx=s([4291597760,4286226898],t.t)
B.bXx=new A.dl("cin-2","Sebaik-baik kalian adalah orang yang paling baik terhadap keluarganya, dan aku adalah orang yang paling baik terhadap keluargaku.","\u062e\u064e\u064a\u0652\u0631\u064f\u0643\u064f\u0645\u0652 \u062e\u064e\u064a\u0652\u0631\u064f\u0643\u064f\u0645\u0652 \u0644\u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u062e\u064e\u064a\u0652\u0631\u064f\u0643\u064f\u0645\u0652 \u0644\u0623\u064e\u0647\u0652\u0644\u0650\u064a","HR. Tirmidzi no. 3895","cinta","Cinta & Keluarga",B.aQx)
B.aQA=s([4293827751,4294958561],t.t)
B.bXH=new A.dl("cin-3","Cinta yang paling sejati adalah cinta yang membawa kita semakin dekat kepada Allah dan mempertemukan kembali di surga-Nya.",null,"Kutipan Mutiara","cinta","Cinta & Keluarga",B.aQA)
B.aQz=s([4292485887,4288099310],t.t)
B.bXw=new A.dl("cin-4","Dan di antara tanda-tanda kekuasaan-Nya ialah Dia menciptakan untukmu pasangan-pasangan dari jenismu sendiri, supaya kamu cenderung dan merasa tenteram kepadanya, dan dijadikan-Nya di antaramu rasa kasih dan sayang.","\u0648\u064e\u0645\u0650\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0647\u0650 \u0623\u064e\u0646\u0652 \u062e\u064e\u0644\u064e\u0642\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u064b\u0627 \u0644\u0651\u0650\u062a\u064e\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u064b \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b","QS. Ar-Rum: 21","cinta","Cinta & Keluarga",B.aQz)
B.aQD=s([4294925882,4294912616],t.t)
