B.agX=new A.qT("Doa Sholat Dhuha","\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0636\u0651\u064f\u062d\u064e\u0627\u0621\u064e \u0636\u064f\u062d\u064e\u0627\u0624\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0647\u064e\u0627\u0621\u064e \u0628\u064e\u0647\u064e\u0627\u0624\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u062c\u064e\u0645\u064e\u0627\u0644\u064e \u062c\u064e\u0645\u064e\u0627\u0644\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0642\u064f\u0648\u0651\u064e\u062a\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u062f\u0652\u0631\u064e\u0629\u064e \u0642\u064f\u062f\u0652\u0631\u064e\u062a\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u0650\u0635\u0652\u0645\u064e\u0629\u064e \u0639\u0650\u0635\u0652\u0645\u064e\u062a\u064f\u0643\u064e. \u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0631\u0650\u0632\u0652\u0642\u0650\u064a\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u0623\u064e\u0646\u0652\u0632\u0650\u0644\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u0650\u062c\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u0639\u0652\u0633\u0650\u0631\u064b\u0627 \u0641\u064e\u064a\u064e\u0633\u0650\u0651\u0631\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0631\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0637\u064e\u0647\u0650\u0651\u0631\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0628\u064e\u0639\u0650\u064a\u0652\u062f\u064b\u0627 \u0641\u064e\u0642\u064e\u0631\u0650\u0651\u0628\u0652\u0647\u064f \u0628\u0650\u062d\u064e\u0642\u0650\u0651 \u0636\u064f\u062d\u064e\u0627\u0626\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0647\u064e\u0627\u0626\u0650\u0643\u064e \u0648\u064e\u062c\u064e\u0645\u064e\u0627\u0644\u0650\u0643\u064e \u0648\u064e\u0642\u064f\u0648\u0651\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u0642\u064f\u062f\u0652\u0631\u064e\u062a\u0650\u0643\u064e \u0622\u062a\u0650\u0646\u0650\u064a\u0652 \u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0652\u0646\u064e","Allaahumma innadh dhuhaa-a dhuhaa-uka, wal bahaa-a bahaa-uka, wal jamaala jamaaluka, wal quwwata quwwatuka, wal qudrata qudratuka, wal 'ishmata 'ishmatuka. Allaahumma in kaana rizqii fis samaa-i fa anzilhu, wa in kaana fil ardhi fa akhrijhu, wa in kaana mu'siran fa yassirhu...","Ya Allah, sesungguhnya waktu dhuha adalah waktu dhuha-Mu, keagungan adalah keagungan-Mu, keindahan adalah keindahan-Mu, kekuatan adalah kekuatan-Mu, kekuasaan adalah kekuasaan-Mu, dan penjagaan adalah penjagaan-Mu...")
B.bkN=s([B.agX],t.Av)
B.bYD=new A.hq("Sholat Dhuha","sunnah","2 hingga 8 Rakaat - Sholat pagi pembuka rezeki","2 - 8 Rakaat","Mulai matahari setinggi tombak (sekitar pk 07.00) sampai menjelang Dzuhur","Sunnah Muakkad","Sebagai sedekah bagi 360 persendian tubuh dan Allah mencukupi kebutuhan rezeki di hari itu.",B.bZ1,null,null,B.b8E,B.bkN)
B.bZi=new A.fi("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0633\u064f\u0646\u064e\u0651\u0629\u064e \u0627\u0644\u0652\u0648\u0650\u062a\u0652\u0631\u0650 \u062b\u064e\u0644\u0627\u064e\u062b\u064e \u0631\u064e\u0643\u064e\u0639\u064e\u0627\u062a\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u0628\u0650\u0644\u064e \u0627\u0644\u0652\u0642\u0650\u0628\u0652\u0644\u064e\u0629\u0650 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii sunnatal witri tsalaatsa raka'aatin mustaqbilal qiblati lillaahi ta'aalaa.","Saya berniat sholat sunnah Witir tiga rakaat menghadap kiblat karena Allah Ta'ala.")
B.c7Y=new A.d9("Tata Cara Sholat Witir 3 Rakaat","Dapat dilakukan 2 rakaat salam lalu ditambah 1 rakaat salam (lebih utama), atau langsung 3 rakaat dengan satu kali salam. Disunnahkan membaca Al-A'la pada rakaat 1, Al-Kafirun pada rakaat 2, dan Al-Ikhlas, Al-Falaq, An-Nas pada rakaat 3.",null,null,null)
B.bbZ=s([B.c7Y],t.I4)
B.bYJ=new A.hq("Sholat Witir","sunnah","1 atau 3 Rakaat - Sholat ganjil penutup malam","1 atau 3 Rakaat (Bisa sampai 11 Rakaat)","Setelah sholat Isya hingga sebelum waktu Subuh","Sunnah Muakkad","Allah itu Maha Ganjil dan menyukai yang ganjil. Menjadi penutup rangkaian ibadah sholat malam.",B.bZi,null,null,B.bbZ,null)
B.bZ2=new A.fi("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0633\u064f\u0646\u064e\u0651\u0629\u064e \u0627\u0644\u0627\u0650\u0633\u0652\u062a\u0650\u062e\u064e\u0627\u0631\u064e\u0629\u0650 \u0631\u064e\u0643\u0652\u0639\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u0628\u0650\u0644\u064e \u0627\u0644\u0652\u0642\u0650\u0628\u0652\u0644\u064e\u0629\u0650 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii sunnatal istikhaarati rak'ataini mustaqbilal qiblati lillaahi ta'aalaa.","Saya berniat sholat sunnah Istikharah dua rakaat menghadap kiblat karena Allah Ta'ala.")
B.c85=new A.d9("Tata Cara Sholat Istikharah","Dilakukan 2 rakaat. Setelah salam, membaca puji-pujian kepada Allah, shalawat, lalu membaca doa istikharah sambil menyebutkan perkara yang dihadapi.",null,null,null)
B.aB0=s([B.c85],t.I4)
B.bYC=new A.hq("Sholat Istikharah","sunnah","2 Rakaat - Memohon petunjuk keputusan terbaik","2 Rakaat","Bisa dikerjakan kapan saja di luar waktu terlarang sholat","Sunnah","Mendapat ketenangan hati dan bimbingan Allah atas pilihan perkara hidup.",B.bZ2,null,null,B.aB0,null)
B.bZ3=new A.fi("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0633\u064f\u0646\u064e\u0651\u0629\u064e \u0627\u0644\u062a\u064e\u0651\u0648\u0652\u0628\u064e\u0629\u0650 \u0631\u064e\u0643\u0652\u0639\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u0628\u0650\u0644\u064e \u0627\u0644\u0652\u0642\u0650\u0628\u0652\u0644\u064e\u0629\u0650 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii sunnatat taubati rak'ataini mustaqbilal qiblati lillaahi ta'aalaa.","Saya berniat sholat sunnah Taubat dua rakaat menghadap kiblat karena Allah Ta'ala.")
B.c8q=new A.d9("Tata Cara Sholat Taubat","Sholat 2 rakaat dengan penuh penyesalan dan kekhusyukan, diakhiri istighfar dan tekad untuk tidak mengulangi perbuatan maksiat.",null,null,null)
B.bfm=s([B.c8q],t.I4)
B.bYA=new A.hq("Sholat Taubat","sunnah","2 Rakaat - Memohon ampunan atas dosa & kesalahan","2 Rakaat","Kapan saja setelah melakukan perbuatan dosa (utama di malam hari)","Sunnah","Allah mengampuni dosa hamba-Nya yang beristighfar dengan sungguh-sungguh.",B.bZ3,null,null,B.bfm,null)
B.bZ9=new A.fi("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0633\u064f\u0646\u064e\u0651\u0629\u064e \u0627\u0644\u0652\u062d\u064e\u0627\u062c\u064e\u0629\u0650 \u0631\u064e\u0643\u0652\u0639\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u0628\u0650\u0644\u064e \u0627\u0644\u0652\u0642\u0650\u0628\u0652\u0644\u064e\u0629\u0650 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii sunnatal haajati rak'ataini mustaqbilal qiblati lillaahi ta'aalaa.","Saya berniat sholat sunnah Hajat dua rakaat menghadap kiblat karena Allah Ta'ala.")
B.c8j=new A.d9("Tata Cara Sholat Hajat","Dikerjakan 2 rakaat salam, dilanjutkan dengan membaca istighfar 100x, shalawat 100x, lalu memanjatkan doa hajat spesifik yang diinginkan.",null,null,null)
B.beZ=s([B.c8j],t.I4)
B.bYG=new A.hq("Sholat Hajat","sunnah","2 hingga 12 Rakaat - Memohon dikabulkannya hajat","2 Rakaat (sampai 12 rakaat)","Kapan saja terutama di keheningan malam hari","Sunnah","Allah memudahkan urusan dunia dan akhirat bagi hamba yang memohon kepada-Nya.",B.bZ9,null,null,B.beZ,null)
B.bZ7=new A.fi("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0639\u064e\u0644\u064e\u0649 \u0647\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u064a\u0650\u0651\u062a\u0650 (\u0627\u0644\u0652\u0645\u064e\u064a\u0650\u0651\u062a\u064e\u0629\u0650) \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e \u062a\u064e\u0643\u0652\u0628\u0650\u064a\u0652\u0631\u064e\u0627\u062a\u064d \u0641\u064e\u0631\u0652\u0636\u064e \u0643\u0650\u0641\u064e\u0627\u064a\u064e\u0629\u064d \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii 'alaa haadzal mayyiti (laki-laki) / haadzihil mayyitati (perempuan) arba'a takbiiraatin fardha kifaayatin lillaahi ta'aalaa.","Saya berniat sholat atas jenazah ini empat takbir fardhu kifayah karena Allah Ta'ala.")
B.c7R=new A.d9("Takbir Pertama (1)","Mengangkat tangan membaca takbir, lalu membaca Surah Al-Fatihah.",null,null,null)
B.c8p=new A.d9("Takbir Kedua (2)","Takbir lalu membaca Shalawat Ibrahimiyah kepada Nabi Muhammad SAW.",null,null,null)
B.c7X=new A.d9("Takbir Ketiga (3)",'Takbir lalu membaca doa ampunan untuk jenazah: "Allaahummaghfir lahu warhamhu..."',"\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f (\u0644\u064e\u0647\u064e\u0627) \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0647\u064f \u0648\u064e\u0639\u064e\u0627\u0641\u0650\u0647\u0650 \u0648\u064e\u0627\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f","Allaahummaghfir lahu (laki-laki) / lahaa (perempuan) warhamhu wa 'aafihi wa'fu 'anhu.","Ya Allah, ampunilah dia, rahmatilah dia, selamatkanlah dia dan maafkanlah kesalahannya.")
B.c8h=new A.d9("Takbir Keempat (4) & Salam","Takbir membaca doa penutup, lalu mengucap salam ke kanan dan ke kiri.",null,null,null)
B.b7J=s([B.c7R,B.c8p,B.c7X,B.c8h],t.I4)
B.bYH=new A.hq("Sholat Jenazah","sunnah","4 Takbir - Tanpa ruku' & tanpa sujud","4 Takbir (Berdiri)","Kapan saja setelah jenazah dimandikan dan dikafani","Fardhu Kifayah","Mendapat pahala sebesar dua gunung Uhud (Qirath) bagi yang menyalatkan hingga menguburkan.",B.bZ7,null,null,B.b7J,null)
B.bZ0=new A.fi("\u0646\u064e\u0648\u064e\u064a\u0652\u062a\u064f \u0627\u0644\u0652\u0648\u064f\u0636\u064f\u0648\u0652\u0621\u064e \u0644\u0650\u0631\u064e\u0641\u0652\u0639\u0650 \u0627\u0644\u0652\u062d\u064e\u062f\u064e\u062b\u0650 \u0627\u0644\u0623\u064e\u0635\u0652\u063a\u064e\u0631\u0650 \u0641\u064e\u0631\u0652\u0636\u064b\u0627 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Nawaitul wudhuu-a liraf'il hadatsil ashghari fardhan lillaahi ta'aalaa.","Saya niat berwudhu untuk menghilangkan hadats kecil fardhu karena Allah Ta'ala.")
B.c8k=new A.d9("1. Membaca Basmalah & Mencuci Telapak Tangan","Mencuci kedua telapak tangan hingga sela-sela jari sebanyak 3 kali.",null,null,null)
B.c82=new A.d9("2. Berkumur-kumur & Istinsyaq","Berkumur-kumur 3 kali dan menghirup air ke hidung lalu mengeluarkannya 3 kali.",null,null,null)
B.c8m=new A.d9("3. Membasuh Wajah & Niat","Membasuh seluruh wajah dari tumbuhnya rambut hingga dagu sebanyak 3 kali sambil berniat wudhu dalam hati.",null,null,null)
B.c8g=new A.d9("4. Membasuh Kedua Tangan Hingga Siku","Membasuh tangan kanan hingga siku 3 kali, lalu tangan kiri 3 kali.",null,null,null)
B.c8e=new A.d9("5. Mengusap Sebagian Kepala / Rambut","Mengusap kepala dengan air sebanyak 3 kali.",null,null,null)
B.c8s=new A.d9("6. Membasuh Kedua Telinga","Mengusap daun telinga luar dan dalam dengan air sebanyak 3 kali.",null,null,null)
B.c8o=new A.d9("7. Membasuh Kedua Kaki Hingga Mata Kaki","Membasuh kaki kanan hingga mata kaki dan sela-sela jari 3 kali, lalu kaki kiri 3 kali.",null,null,null)
B.c7U=new A.d9("8. Tertib & Berdoa Setelah Wudhu","Melakukan seluruh rukun secara berurutan dan membaca doa setelah wudhu menghadap kiblat.",null,null,null)
B.b9j=s([B.c8k,B.c82,B.c8m,B.c8g,B.c8e,B.c8s,B.c8o,B.c7U],t.I4)
B.agU=new A.qT("Doa Setelah Berwudhu","\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0652 \u0644\u0627\u064e \u0625\u0650\u0644\u0670\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0651\u064e \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064b\u0627 \u0639\u064e\u0628\u0652\u062f\u064f\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0652\u0644\u064f\u0647\u064f. \u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u0650\u064a\u0652\u0646\u064e \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0637\u064e\u0647\u0650\u0651\u0631\u0650\u064a\u0652\u0646\u064e \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0652\u0646\u064e","Asyhadu allaa ilaaha illallaahu wahdahu laa syariika lah, wa asyhadu anna Muhammadan 'abduhu wa rasuuluh. Allaahummaj'alnii minat tawwaabiina waj'alnii minal mutathahhiriina waj'alnii min 'ibaadikash shaalihiin.","Aku bersaksi tiada Tuhan selain Allah Yang Maha Esa tiada sekutu bagi-Nya, dan aku bersaksi Muhammad adalah hamba dan utusan-Nya. Ya Allah, jadikanlah aku termasuk golongan orang-orang yang bertaubat, jadikanlah aku termasuk golongan orang-orang yang bersuci, dan jadikanlah aku termasuk hamba-hamba-Mu yang shalih.")
B.bdp=s([B.agU],t.Av)
B.bYI=new A.hq("Tata Cara Berwudhu","bersuci","Panduan rukun, sunnah, & doa setelah wudhu","","","Syarat Sah Sholat (Wajib Bersuci)","Menggugurkan dosa-dosa dari setiap anggota tubuh yang dibasuh bersama tetesan air wudhu.",B.bZ0,null,null,B.b9j,B.bdp)
B.bZe=new A.fi("\u0646\u064e\u0648\u064e\u064a\u0652\u062a\u064f \u0627\u0644\u062a\u0651\u064e\u064a\u064e\u0645\u0651\u064f\u0645\u064e \u0644\u0627\u0650\u0633\u0652\u062a\u0650\u0628\u064e\u0627\u062d\u064e\u0629\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0641\u064e\u0631\u0652\u0636\u064b\u0627 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Nawaitut tayammuma listibaahatish shalaati fardhan lillaahi ta'aalaa.","Saya berniat tayammum untuk dapat melaksanakan sholat fardhu karena Allah Ta'ala.")
B.c7S=new A.d9("1. Meletakkan Telapak Tangan pada Debu Suci","Menepukkan kedua telapak tangan ke permukaan yang berdebu bersih dan suci, lalu meniupnya perlahan.",null,null,null)
B.c8c=new A.d9("2. Mengusap Wajah","Mengusapkan debu pada kedua tangan ke seluruh permukaan wajah sambil berniat.",null,null,null)
B.c8a=new A.d9("3. Mengusap Kedua Tangan Hingga Siku","Menepukkan tangan kembali ke debu di tempat berbeda, lalu mengusapkannya ke tangan kanan hingga siku dan tangan kiri hingga siku.",null,null,null)
B.b8C=s([B.c7S,B.c8c,B.c8a],t.I4)
B.bYK=new A.hq("Tata Cara Tayammum","bersuci","Bersuci dengan debu suci saat tidak ada air","","","Rukhsah (Keringanan) Pengganti Wudhu / Mandi","Keringanan dari Allah agar ibadah sholat tetap dapat ditunaikan dalam kondisi darurat.",B.bZe,null,null,B.b8C,null)
B.c89=new A.d9("1. Membaca Istighfar (3x)","Memohon ampunan kepada Allah setelah mengucap salam.","\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0644\u0647\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0652\u0645\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0652 \u0644\u0627\u064e \u0625\u0650\u0644\u0670\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064f\u0651 \u0627\u0644\u0652\u0642\u064e\u064a\u064f\u0651\u0648\u0652\u0645\u064f \u0648\u064e\u0623\u064e\u062a\u064f\u0648\u0652\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 (\u0663x)","Astaghfirullaahal 'azhiimal ladzii laa ilaaha illaa huwal hayyul qayyuumu wa atuubu ilaih (3x)","Aku memohon ampun kepada Allah Yang Maha Agung, yang tiada Tuhan selain Dia, Yang Maha Hidup lagi Maha Berdiri Sendiri, dan aku bertaubat kepada-Nya.")
B.c8_=new A.d9("2. Membaca Doa Keselamatan (Allaahumma Antas Salaam)","Memuji Allah sebagai sumber kedamaian.","\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0633\u0651\u064e\u0644\u0627\u064e\u0645\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0633\u0651\u064e\u0644\u0627\u064e\u0645\u064f \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u064a\u064e\u0627 \u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0644\u0627\u064e\u0644\u0650 \u0648\u064e\u0627\u0644\u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0645\u0650","Allaahumma antas salaam wa minkas salaam tabaarakta yaa dzal jalaali wal ikraam.","Ya Allah, Engkaulah As-Salam (keselamatan) dan dari-Mu lah datangnya keselamatan, Maha Berkah Engkau wahai Dzat Yang Memiliki Keagungan dan Kemuliaan.")
B.c81=new A.d9("3. Membaca Tasbih, Tahmid, & Takbir (masing-masing 33x)","Mengagungkan Allah sebanyak 33 kali.","\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0647\u0650 (\u0663\u0663x)\n\u0627\u064e\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u0670\u0647\u0650 (\u0663\u0663x)\n\u0627\u0644\u0644\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f (\u0663\u0663x)","Subhaanallaah (33x)\nAlhamdulillaah (33x)\nAllaahu Akbar (33x)","Maha Suci Allah (33x), Segala Puji bagi Allah (33x), Allah Maha Besar (33x).")
B.c8f=new A.d9("4. Membaca Tahlil Penyempurna 100x","Membaca pengesaan Allah di akhir tasbih.","\u0644\u0627\u064e \u0625\u0650\u0644\u0670\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0652 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u0652\u062a\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064c","Laa ilaaha illallaahu wahdahu laa syariika lah, lahul mulku wa lahul hamdu yuhyii wa yumiitu wa huwa 'alaa kulli syai-in qadiir.","Tiada Tuhan selain Allah Yang Maha Esa tiada sekutu bagi-Nya, milik-Nya kerajaan dan milik-Nya segala puji, Yang Menghidupkan dan Mematikan, dan Dia Maha Kuasa atas segala sesuatu.")
B.c8n=new A.d9("5. Membaca Ayat Kursi","Rasulullah bersabda barangsiapa membaca Ayat Kursi setiap usai sholat wajib, tidak ada yang menghalanginya masuk surga kecuali kematian.","\u0627\u0644\u0644\u0651\u0670\u0647\u064f \u0644\u064e\u0627\u0653 \u0627\u0650\u0644\u0670\u0647\u064e \u0627\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u064f \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u064f\u0648\u0652\u0645\u064f\u06da \u0644\u064e\u0627 \u062a\u064e\u0627\u0652\u062e\u064f\u0630\u064f\u0647\u0657 \u0633\u0650\u0646\u064e\u0629\u064c \u0648\u0651\u064e\u0644\u064e\u0627 \u0646\u064e\u0648\u0652\u0645\u064c\u06d7 \u0644\u064e\u0647\u0657 \u0645\u064e\u0627 \u0641\u0650\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u0670\u0648\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u0649 \u0627\u0644\u0652\u0627\u064e\u0631\u0652\u0636\u0650\u06d7 \u0645\u064e\u0646\u0652 \u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0652 \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u0657\u0653 \u0627\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0650\u0630\u0652\u0646\u0650\u0647\u0656\u06d7 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u064e\u064a\u0652\u062f\u0650\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0652\u0637\u064f\u0648\u0652\u0646\u064e \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0651\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0656\u0653 \u0627\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0634\u064e\u0627\u06e4\u0621\u064e\u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0631\u0652\u0633\u0650\u064a\u0651\u064f\u0647\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u0670\u0648\u0670\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0627\u064e\u0631\u0652\u0636\u064e\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0640\u0654\u064f\u0648\u0652\u062f\u064f\u0647\u0657 \u062d\u0650\u0641\u0652\u0638\u064f\u0647\u064f\u0645\u064e\u0627\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0652\u0645\u064f","Allaahu laa ilaaha illaa huwal hayyul qayyuum, laa ta'khudzuhuu sinatuw wa laa naum, lahuu maa fis samaawaati wa maa fil ardh...","Allah, tidak ada tuhan selain Dia. Yang Mahahidup, Yang terus-menerus mengurus (makhluk-Nya), tidak mengantuk dan tidak tidur. Milik-Nya apa yang ada di langit dan apa yang ada di bumi...")
